<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Solar System</title>
<style>
  html, body { margin: 0; height: 100%; overflow: hidden; background: #05060a; }
  canvas { display: block; }
</style>
</head>
<body>
<canvas id="sky"></canvas>
<script>
const canvas = document.getElementById('sky');
const ctx = canvas.getContext('2d');
let W, H, cx, cy, scale;

function resize() {
  W = canvas.width = window.innerWidth;
  H = canvas.height = window.innerHeight;
  cx = W / 2;
  cy = H / 2;
  scale = Math.min(W, H) / 2.2;
}
window.addEventListener('resize', resize);
resize();

// Starfield
const stars = [];
for (let i = 0; i < 300; i++) {
  stars.push({
    x: Math.random(),
    y: Math.random(),
    r: Math.random() * 1.3 + 0.2,
    tw: Math.random() * Math.PI * 2,
    ts: 0.5 + Math.random() * 1.5
  });
}

const planets = [
  { name: 'Mercury', r: 0.16, size: 3.2,  speed: 4.15, color: '#b9a68a', angle: 0.4 },
  { name: 'Venus',   r: 0.26, size: 5.2,  speed: 1.62, color: '#e6c98a', angle: 2.1 },
  { name: 'Earth',   r: 0.38, size: 5.6,  speed: 1.0,  color: '#6fa8dc', angle: 4.0, moon: { r: 12, size: 1.8, speed: 6.0 } },
  { name: 'Mars',    r: 0.50, size: 4.2,  speed: 0.53, color: '#d1683f', angle: 1.2 },
  { name: 'Jupiter', r: 0.68, size: 11.5, speed: 0.28, color: '#d8b48c', angle: 3.3, bands: true },
  { name: 'Saturn',  r: 0.86, size: 9.5,  speed: 0.19, color: '#e3d3a5', angle: 5.2, ring: true },
  { name: 'Neptune', r: 1.0,  size: 6.0,  speed: 0.11, color: '#5f7fd8', angle: 0.9 }
];

let t = 0;
let last = performance.now();

function draw(now) {
  const dt = Math.min((now - last) / 1000, 0.05);
  last = now;
  t += dt;

  // Background
  ctx.fillStyle = '#05060a';
  ctx.fillRect(0, 0, W, H);

  // Stars (twinkle)
  for (const s of stars) {
    const a = 0.35 + 0.65 * (0.5 + 0.5 * Math.sin(t * s.ts + s.tw));
    ctx.globalAlpha = a;
    ctx.fillStyle = '#cfd6e4';
    ctx.beginPath();
    ctx.arc(s.x * W, s.y * H, s.r, 0, Math.PI * 2);
    ctx.fill();
  }
  ctx.globalAlpha = 1;

  // Orbit paths
  ctx.strokeStyle = 'rgba(140,160,200,0.14)';
  ctx.lineWidth = 1;
  for (const p of planets) {
    ctx.beginPath();
    ctx.arc(cx, cy, p.r * scale, 0, Math.PI * 2);
    ctx.stroke();
  }

  // Sun glow
  const sunR = Math.max(14, scale * 0.075);
  const pulse = 1 + 0.05 * Math.sin(t * 2);
  let g = ctx.createRadialGradient(cx, cy, 0, cx, cy, sunR * 6 * pulse);
  g.addColorStop(0, 'rgba(255,220,120,0.55)');
  g.addColorStop(0.25, 'rgba(255,150,50,0.22)');
  g.addColorStop(1, 'rgba(255,120,30,0)');
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.arc(cx, cy, sunR * 6 * pulse, 0, Math.PI * 2);
  ctx.fill();

  // Sun body
  g = ctx.createRadialGradient(cx - sunR * 0.3, cy - sunR * 0.3, sunR * 0.1, cx, cy, sunR);
  g.addColorStop(0, '#fff6d0');
  g.addColorStop(0.5, '#ffcc55');
  g.addColorStop(1, '#ff8a20');
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.arc(cx, cy, sunR, 0, Math.PI * 2);
  ctx.fill();

  // Planets
  for (const p of planets) {
    const a = p.angle + t * p.speed * 0.4;
    const px = cx + Math.cos(a) * p.r * scale;
    const py = cy + Math.sin(a) * p.r * scale * 0.92; // slight elliptical feel

    // Saturn ring behind
    if (p.ring) {
      ctx.save();
      ctx.translate(px, py);
      ctx.rotate(-0.45);
      ctx.strokeStyle = 'rgba(220,205,160,0.55)';
      ctx.lineWidth = 2.5;
      ctx.beginPath();
      ctx.ellipse(0, 0, p.size * 2.1, p.size * 0.75, 0, 0, Math.PI * 2);
      ctx.stroke();
      ctx.restore();
    }

    // Body
    const pg = ctx.createRadialGradient(px - p.size * 0.4, py - p.size * 0.4, p.size * 0.15, px, py, p.size);
    pg.addColorStop(0, p.color);
    pg.addColorStop(1, shade(p.color, 0.35));
    ctx.fillStyle = pg;
    ctx.beginPath();
    ctx.arc(px, py, p.size, 0, Math.PI * 2);
    ctx.fill();

    // Jupiter bands
    if (p.bands) {
      ctx.save();
      ctx.beginPath();
      ctx.arc(px, py, p.size, 0, Math.PI * 2);
      ctx.clip();
      ctx.strokeStyle = 'rgba(150,110,70,0.45)';
      ctx.lineWidth = 1.4;
      for (let i = -2; i <= 2; i++) {
        ctx.beginPath();
        ctx.moveTo(px - p.size, py + i * p.size * 0.35);
        ctx.lineTo(px + p.size, py + i * p.size * 0.35);
        ctx.stroke();
      }
      ctx.restore();
    }

    // Saturn ring front half
    if (p.ring) {
      ctx.save();
      ctx.translate(px, py);
      ctx.rotate(-0.45);
      ctx.strokeStyle = 'rgba(235,220,175,0.8)';
      ctx.lineWidth = 2.5;
      ctx.beginPath();
      ctx.ellipse(0, 0, p.size * 2.1, p.size * 0.75, 0, 0, Math.PI);
      ctx.stroke();
      ctx.restore();
    }

    // Moon for Earth
    if (p.moon) {
      const ma = t * p.moon.speed;
      const mx = px + Math.cos(ma) * p.moon.r;
      const my = py + Math.sin(ma) * p.moon.r;
      ctx.fillStyle = '#c9c9c9';
      ctx.beginPath();
      ctx.arc(mx, my, p.moon.size, 0, Math.PI * 2);
      ctx.fill();
    }
  }

  requestAnimationFrame(draw);
}

function shade(hex, f) {
  const n = parseInt(hex.slice(1), 16);
  const r = Math.round(((n >> 16) & 255) * f);
  const g = Math.round(((n >> 8) & 255) * f);
  const b = Math.round((n & 255) * f);
  return `rgb(${r},${g},${b})`;
}

requestAnimationFrame(draw);
</script>
</body>
</html>
